CREATE OR REPLACE FUNCTION public.network_send_wave(_distribution uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.trip_distributions;radius integer;wave uuid;p record;n integer:=0;oid uuid;cfg public.trip_network_settings;BEGIN
SELECT * INTO d FROM public.trip_distributions WHERE id=_distribution FOR UPDATE;
IF NOT public.network_source_access(_distribution,true) THEN RAISE EXCEPTION 'Distribution permission required';END IF;
IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='nearby_matching' AND enabled) THEN RAISE EXCEPTION 'Nearby matching intentionally off';END IF;
IF d.selected_workspace_id IS NOT NULL OR d.expires_at<=now() OR d.pickup_date<current_date OR d.status NOT IN ('ready','offers_sent','negotiating','needs_attention') OR EXISTS(SELECT 1 FROM public.provider_trip_offers WHERE distribution_id=d.id AND status IN ('pending','countered','revised') AND expires_at>now()) THEN RAISE EXCEPTION 'Prior wave still pending or source unavailable';END IF;
IF d.funding_required AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(d.funding_versions) f WHERE f->>'funded'='true' AND (f->>'offerVersionAmountCents')::integer=d.amount_cents AND f->>'acceptedAt' IS NOT NULL) THEN RAISE EXCEPTION 'Authoritative referral funding required';END IF;
IF d.request_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.ride_requests WHERE id=d.request_id AND NOT is_test AND trip_kind='passenger' AND status NOT IN ('canceled','cancelled','declined','denied','completed') AND assigned_provider_id IS NULL) THEN RAISE EXCEPTION 'Source unavailable';END IF;
IF d.trip_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.trips WHERE id=d.trip_id AND trip_kind='passenger' AND status NOT IN ('completed','canceled','cancelled') AND driver_id IS NULL AND vehicle_id IS NULL AND network_provider_workspace_id IS NULL) THEN RAISE EXCEPTION 'Source unavailable';END IF;
SELECT * INTO cfg FROM public.trip_network_settings WHERE id=true;
IF cfg.id IS NULL THEN RAISE EXCEPTION 'Configure wave limits before launch';END IF;
radius:=CASE coalesce(d.current_radius,0) WHEN 0 THEN 20 WHEN 20 THEN 50 WHEN 50 THEN 100 WHEN 100 THEN 200 ELSE NULL END;
IF radius IS NULL OR radius>cfg.max_radius THEN RAISE EXCEPTION 'Configured expansion limit reached';END IF;
UPDATE public.provider_trip_offers SET status='expired',updated_at=now() WHERE distribution_id=d.id AND status IN ('pending','countered','revised') AND expires_at<=now();
INSERT INTO public.trip_distribution_waves(distribution_id,radius_miles,sent_by) VALUES(d.id,radius,auth.uid()) RETURNING id INTO wave;
FOR p IN SELECT * FROM public.network_matching_candidates(d.id,radius) WHERE excluded='' ORDER BY score DESC,workspace LIMIT cfg.max_candidates LOOP
INSERT INTO public.provider_trip_offers(distribution_id,wave_id,provider_workspace_id,amount_cents,expires_at,match_explanation) VALUES(d.id,wave,p.workspace,d.amount_cents,least(d.expires_at,now()+make_interval(mins=>cfg.response_minutes)),p.explanation) ON CONFLICT(distribution_id,provider_workspace_id) DO NOTHING RETURNING id INTO oid;
IF oid IS NOT NULL THEN n:=n+1;PERFORM public.network_notify(p.workspace,'New offer received',oid,false);END IF;END LOOP;
UPDATE public.trip_distributions SET current_radius=radius,status='offers_sent',updated_at=now() WHERE id=d.id;PERFORM public.network_audit(d.id,NULL,'wave_sent',jsonb_build_object('radius',radius,'recipients',n));RETURN jsonb_build_object('radius',radius,'recipients',n);END $$;
CREATE FUNCTION public.withdraw_nearby_distribution(_distribution uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM 1 FROM public.trip_distributions WHERE id=_distribution FOR UPDATE;IF NOT public.network_source_access(_distribution,true) OR EXISTS(SELECT 1 FROM public.trip_distributions WHERE id=_distribution AND selected_workspace_id IS NOT NULL) THEN RAISE EXCEPTION 'Distribution unavailable';END IF;
UPDATE public.trip_distributions SET status='closed',updated_at=now() WHERE id=_distribution;UPDATE public.provider_trip_offers SET status='closed',updated_at=now() WHERE distribution_id=_distribution AND status IN ('pending','countered','revised');PERFORM public.network_audit(_distribution,NULL,'withdrawn','{}');END $$;
REVOKE ALL ON FUNCTION public.withdraw_nearby_distribution(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.withdraw_nearby_distribution(uuid) TO authenticated;
CREATE FUNCTION public.nearby_offer_insert_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_launch_flags WHERE key='nearby_matching' AND enabled) OR NOT EXISTS(SELECT 1 FROM public.provider_network_profiles p WHERE p.workspace_id=NEW.provider_workspace_id AND p.nearby_opt_in AND p.matching_consent->>'version'='2026-11-15') THEN RAISE EXCEPTION 'Nearby offers disabled or consent missing';END IF;RETURN NEW;END $$;
CREATE TRIGGER nearby_offer_insert_guard BEFORE INSERT ON public.provider_trip_offers FOR EACH ROW EXECUTE FUNCTION public.nearby_offer_insert_guard();
CREATE FUNCTION public.matching_source_stop_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record;stop boolean;BEGIN
IF TG_TABLE_NAME='trips' THEN stop:=NEW.status IN ('completed','canceled','cancelled','denied') OR NEW.driver_id IS NOT NULL OR NEW.vehicle_id IS NOT NULL OR NEW.network_provider_workspace_id IS NOT NULL;ELSE stop:=NEW.status IN ('completed','canceled','cancelled','declined','denied','unavailable') OR NEW.assigned_provider_id IS NOT NULL;END IF;
IF stop THEN FOR d IN SELECT id FROM public.trip_distributions WHERE (TG_TABLE_NAME='trips' AND trip_id=NEW.id OR TG_TABLE_NAME='ride_requests' AND request_id=NEW.id) AND selected_workspace_id IS NULL AND status NOT IN ('closed','canceled','unavailable') FOR UPDATE LOOP
UPDATE public.trip_distributions SET status='closed',updated_at=now() WHERE id=d.id;UPDATE public.provider_trip_offers SET status='closed',updated_at=now() WHERE distribution_id=d.id AND status IN ('pending','countered','revised');PERFORM public.network_audit(d.id,NULL,'source_no_longer_eligible','{}');END LOOP;END IF;RETURN NEW;END $$;
CREATE TRIGGER zz_matching_trip_stop AFTER UPDATE OF status,driver_id,vehicle_id ON public.trips FOR EACH ROW EXECUTE FUNCTION public.matching_source_stop_guard();
CREATE TRIGGER zz_matching_request_stop AFTER UPDATE OF status,assigned_provider_id ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.matching_source_stop_guard();